function P({registerIndicator:f,nulls:y}){f({id:"oa-hlv",name:"High-Low Volatility (HLV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1,tooltip:"Period for smoothing the Parkinson estimator."},{key:"annualize",type:"boolean",label:"Annualize Volatility",default:!0,tooltip:"Annualize the volatility output."},{key:"annualPeriods",type:"number",label:"Annual Periods",default:252,min:1,max:1e5,step:1,tooltip:"Number of periods in a year for annualization (252 for daily, 52 for weekly)."}],plots:[{key:"hlv",type:"line",title:"HLV",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,l){const i=Math.max(1,Math.floor(Number(l.length)||20)),b=l.annualize!==!1,d=Math.max(1,Math.floor(Number(l.annualPeriods)||252)),g=1e-10,k=.3606737602,h=1/i,c=new Array(n.length).fill(NaN);let t=0,o=1,r=NaN,s=NaN;for(let e=0;e<n.length;e++){const v=Number(n[e].high),M=Number(n[e].low),w=Math.log(v),F=Math.log(M),N=w-F,a=k*N*N;Number.isFinite(a)&&(t=Number.isFinite(r)?(r*(i-1)+a)/i:a,o=Number.isFinite(s)?(1-h)*s:1-h);const p=o>g&&Number.isFinite(t)?t/(1-o):t,u=Number.isFinite(p)?p:a,m=Number.isFinite(u)&&u>=0?Math.sqrt(u):NaN;c[e]=b&&Number.isFinite(m)?m*Math.sqrt(d):m,r=t,s=o}return{hlv:y(c)}}})}export{P as default};
